import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const n="/depgate/screenshots/settings-webhooks.png",s="/depgate/screenshots/webhook-add.png",u=JSON.parse('{"title":"Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"admin/webhooks.md","filePath":"admin/webhooks.md"}'),d={name:"admin/webhooks.md"};function i(h,e,l,c,p,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h1><p>Webhooks send DepGate alerts to other systems as they happen: a chat channel, a ticketing system, or your own automation. Manage them under <strong>Settings → Webhooks</strong> (Security role). To send every event to a SIEM in batches, use <a href="./log-streaming">Log streaming</a> instead.</p><p><img src="'+n+'" alt="Webhooks"></p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Sent when</th></tr></thead><tbody><tr><td><code>package_blocked</code></td><td>A download is blocked by a policy, the malware list or namespace protection.</td></tr><tr><td><code>malware_requested</code></td><td>Someone requests a package on the malware list, whether it is blocked or let through.</td></tr><tr><td><code>dependency_confusion_blocked</code></td><td>Namespace protection blocks a reserved name from a public registry.</td></tr><tr><td><code>namespace_collision</code></td><td>The collision check finds one of your internal names on a public registry.</td></tr></tbody></table><p>A new webhook sends the first three.</p><h2 id="add-a-webhook" tabindex="-1">Add a webhook <a class="header-anchor" href="#add-a-webhook" aria-label="Permalink to &quot;Add a webhook&quot;">​</a></h2><ol><li>Choose <strong>Add webhook</strong>.</li><li>Enter the <strong>Endpoint URL</strong> that will receive the events.</li><li>Optionally enter a <strong>Signing secret</strong>. Each request then carries an HMAC signature your endpoint can verify.</li><li>Select the <strong>Events</strong> to send.</li><li>Leave <strong>Send events now</strong> selected and choose <strong>Create</strong>.</li></ol><p><img src="'+s+'" alt="Adding a webhook"></p><p>Choose <strong>Send test event</strong> (the paper-plane icon) to post a <code>test</code> event and see your endpoint&#39;s answer immediately.</p><h2 id="payload-and-headers" tabindex="-1">Payload and headers <a class="header-anchor" href="#payload-and-headers" aria-label="Permalink to &quot;Payload and headers&quot;">​</a></h2><p>DepGate sends an HTTP <code>POST</code> with a JSON body. Each event has a unique, time-ordered ID.</p><table tabindex="0"><thead><tr><th>Header</th><th>Contents</th></tr></thead><tbody><tr><td><code>X-DepGate-Event-Id</code></td><td>The event ID (also <code>id</code> in the body). A redelivered event keeps its ID: use it to ignore duplicates.</td></tr><tr><td><code>X-DepGate-Delivery-Attempt</code></td><td>The attempt number (also <code>attempt</code> in the body).</td></tr><tr><td><code>X-DepGate-Signature</code></td><td>HMAC-SHA256 of the request body, using the signing secret. Present when a secret is set.</td></tr></tbody></table><p>Verify the signature by computing the HMAC-SHA256 of the raw body with your secret and comparing it with the header. Events are not guaranteed to arrive in order; sort by the <code>timestamp</code> field or the event ID.</p><p>Identical <code>package_blocked</code> and <code>malware_requested</code> events within 5 minutes (<code>WEBHOOK_COALESCE_SECONDS</code>) are grouped: the first is sent at once, and one follow-up carries the count and the time of the first and last repeat.</p><h2 id="delivery-and-retries" tabindex="-1">Delivery and retries <a class="header-anchor" href="#delivery-and-retries" aria-label="Permalink to &quot;Delivery and retries&quot;">​</a></h2><ul><li>A <code>2xx</code> answer counts as delivered.</li><li>A timeout, connection error, <code>408</code>, <code>425</code>, <code>429</code> or <code>5xx</code> is retried up to 8 times with a doubling delay starting at 30 seconds, about 2 hours in total. A <code>Retry-After</code> header is respected up to one hour.</li><li>Any other <code>4xx</code> answer fails at once.</li><li>At most 5 requests per second go to one host.</li></ul><h2 id="delivery-history" tabindex="-1">Delivery history <a class="header-anchor" href="#delivery-history" aria-label="Permalink to &quot;Delivery history&quot;">​</a></h2><p>Choose the history icon on a webhook to open <strong>Deliveries</strong>: every event sent in the last 30 days, newest first, with its status (<em>Delivered</em>, <em>Retrying</em>, <em>Failed</em>, <em>Skipped</em>) and the exact payload. Choose <strong>Redeliver</strong> to send an event again with the same event ID.</p><h2 id="failing-webhooks" tabindex="-1">Failing webhooks <a class="header-anchor" href="#failing-webhooks" aria-label="Permalink to &quot;Failing webhooks&quot;">​</a></h2><p>While deliveries keep failing, the list shows how many failed in a row and the last error. After 20 consecutive failures, DepGate <strong>turns the webhook off automatically</strong>, shows a notice on the Dashboard, and records the change in the Audit Log. Events that occur while it is off are kept as <em>Skipped</em>.</p><p>When the endpoint works again, choose <strong>Turn on</strong>. DepGate offers to deliver the skipped events from the last 7 days, in order, with their original event IDs.</p>',22)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
